def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_me, last_op = history[-1]

    # Count overall opponent behavior
    opp_d = 0
    opp_c = 0
    my_d = 0
    for me, op in history:
        if op == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if me == 'D':
            my_d += 1

    opp_rate = opp_c / n

    # Recent window (last 10)
    recent = history[-10:] if n >= 10 else history
    r_opp_d = 0
    r_opp_c = 0
    r_me_d = 0
    for me, op in recent:
        if op == 'D':
            r_opp_d += 1
        else:
            r_opp_c += 1
        if me == 'D':
            r_me_d += 1
    r_len = len(recent)
    r_rate = r_opp_c / r_len

    # Detect opponent defection streak at end
    d_streak = 0
    for me, op in reversed(history):
        if op == 'D':
            d_streak += 1
        else:
            break
    c_streak = 0
    for me, op in reversed(history):
        if op == 'C':
            c_streak += 1
        else:
            break

    # Strong defector: always defect
    if opp_d > 0 and opp_c == 0:
        return 'D'
    if opp_rate <= 0.15 and n >= 5:
        return 'D'

    # Strong cooperator: exploit near end, otherwise mostly cooperate
    if opp_d == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # End-game exploitation if opponent is quite cooperative
    if n >= 94:
        if opp_rate >= 0.75:
            return 'D'
        if opp_rate >= 0.55 and r_me_d == 0:
            return 'D'
        if opp_rate < 0.4:
            return 'D'
        return 'C'

    # If opponent is highly cooperative overall, cooperate
    if opp_rate >= 0.85:
        # rare probe
        if n % 17 == 0 and n > 10 and d_streak == 0:
            return 'D'
        return 'C'

    # If opponent mostly defecting
    if opp_rate <= 0.3:
        # avoid being exploited; probe occasionally to see if recoverable
        if d_streak >= 4:
            return 'D'
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Mid-range opponent. Tit-for-tat-ish with forgiveness.
    if last_op == 'D':
        # Retaliate, but if opponent's defection is isolated, try quick recovery
        if d_streak == 1 and opp_rate >= 0.55:
            # forgive with moderate probability, but alternate to avoid exploitation
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if d_streak >= 3:
            return 'D'
        # Moderate streak
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # last_op == 'C'
    if last_me == 'D':
        # We defected and opponent cooperated: they are forgiving -> cooperate but exploit occasionally
        if opp_rate >= 0.7 and d_streak == 0:
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        return 'C'

    # Both cooperated last round
    if d_streak == 0:
        # Occasionally probe when opponent cooperated for a long stretch
        if c_streak >= 6 and opp_rate >= 0.6:
            if rng.random() < 0.08:
                return 'D'
        if c_streak >= 10 and opp_rate >= 0.5:
            if n % 13 == 0:
                return 'D'
        return 'C'

    return 'C'
